package ch.bbw.zork;/** * Author:  Michael Kolling, Version: 1.1, Date: August 2000 * refactoring: Rinaldo Lanza, September 2020 */import java.util.ArrayList;import java.util.HashMap;import java.util.List;import java.util.stream.Collectors;public class Room {	private String country;	private String description;	private HashMap<String, Room> neighbours;	private Item item;	public Room(String country, String description) {		this.country = country;		this.description = description;		this.neighbours = new HashMap<>();	}	public void addNeighbour(Room neighbour) {		neighbours.put(neighbour.getCountry(), neighbour);		neighbour.neighbours.put(this.country, this);	}	public void addItem(Item item) {		this.item = item;	}	public String shortDescription() {		return description;	}	public String getCountry() {		return country;	}	public String longDescription() {		StringBuilder stringBuilder = new StringBuilder("You are in " + description + itemString() + ".\n");		stringBuilder.append(exitString());		return stringBuilder.toString();	}	private String exitString() {		return "Neighbours: " + String.join(" ", neighbours.keySet());	}	private String itemString() {		if (item == null) {			return " which has no item";		} else {			return " which has " + item.getName();		}	}	public Room nextRoom(String country) {		return neighbours.get(country);	}}